{"path":"assets/css/styles.css","content":"/* Core styles for clinic_modern aesthetic */
:root{--brand:#4a6a54;--accent:#8bbf9f;--muted:#6b6b6b;--glass:rgba(255,255,255,0.6);--bg:#fbfbfa}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;line-height:1.45;color:#222;background:var(--bg)}
.container{max-width:1100px;margin:0 auto;padding:24px}
.site-header{background:linear-gradient(180deg, rgba(255,255,255,0.9), rgba(255,255,255,0.8));backdrop-filter:blur(6px);border-bottom:1px solid #eee}
.site-header .container{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:var(--brand);text-decoration:none;font-size:1.1rem}
.nav{margin-left:auto;display:flex;gap:18px;align-items:center}
.nav a{color:#333;text-decoration:none;padding:8px}
.nav .cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:6px}
.nav-toggle{display:none;background:none;border:0;font-size:1.2rem}

.hero{padding:48px 0;background-size:cover;background-repeat:no-repeat;background-position:center;position:relative}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:start}
.hero-copy h1{margin:0 0 8px;font-size:2rem;color:var(--brand)}
.lead{color:var(--muted);margin-bottom:16px}
.hero-aside .card{background:linear-gradient(180deg, rgba(255,255,255,0.85), rgba(255,255,255,0.75));padding:18px;border-radius:10px;border:1px solid #eef}
.btn{display:inline-block;background:#fff;border:1px solid #ddd;padding:8px 12px;border-radius:8px;text-decoration:none;color:var(--brand)}
.btn.primary{background:var(--brand);color:#fff;border-color:transparent}
.btn.ghost{background:transparent}
.btn.large{padding:14px 20px;font-size:1.05rem}

.section{padding:48px 0;border-top:1px solid #f2f2f2}
.ritual .split{display:grid;grid-template-columns:1fr 380px;gap:28px}
.muted{color:var(--muted)}
.cards{display:flex;gap:18px;flex-wrap:wrap}
.card{background:#fff;padding:18px;border-radius:12px;border:1px solid #eee;flex:1;min-width:240px}
.price{font-weight:700;color:var(--brand)}
.pricing-table{width:100%;border-collapse:collapse;margin-top:14px}
.pricing-table th, .pricing-table td{padding:12px;border:1px solid #eee;text-align:left}
.expect-list{display:flex;flex-direction:column;gap:8px}
.faq .accordion .item{border-bottom:1px solid #f0f0f0}
.faq .q{width:100%;text-align:left;padding:14px;background:none;border:0;font-weight:600}
.faq .a{padding:0 14px 18px;color:var(--muted);display:none}
.cta{background:linear-gradient(90deg, rgba(138,191,159,0.08), rgba(74,106,84,0.03));text-align:center;padding:36px;border-radius:10px}
.cta .btn{margin-top:12px}
.site-footer{border-top:1px solid #eee;background:transparent;padding:24px 0}
.foot-grid{display:flex;justify-content:space-between;align-items:center}

/* Responsive */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .ritual .split{grid-template-columns:1fr}
  .nav{display:none}
  .nav-toggle{display:block;margin-left:auto}
}

/* Decorative SVG mask over sections using the external pattern */
.section{background-image:linear-gradient(180deg, rgba(255,255,255,0.6), rgba(255,255,255,0.9));background-blend-mode:overlay}

/* Accessibility focus states */
a:focus,button:focus{outline:3px solid rgba(139,191,159,0.4);outline-offset:2px}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Mobile nav toggle
  var nav = document.getElementById('nav');
  var btn = document.getElementById('navToggle');
  if(btn && nav){
    btn.addEventListener('click',function(){
      var expanded = nav.style.display === 'flex';
      nav.style.display = expanded ? '' : 'flex';
      nav.style.flexDirection = 'column';
    });
  }

  // Smooth scroll for in-page links
  document.querySelectorAll('a[href^="#"]').forEach(function(anchor){
    anchor.addEventListener('click',function(e){
      e.preventDefault();
      var target = document.querySelector(this.getAttribute('href'));
      if(target) target.scrollIntoView({behavior:'smooth',block:'start'});
    });
  });

  // FAQ accordion
  document.querySelectorAll('.faq .q').forEach(function(q){
    q.addEventListener('click',function(){
      var a = this.nextElementSibling;
      var open = a.style.display === 'block';
      // close others
      document.querySelectorAll('.faq .a').forEach(function(x){x.style.display='none'});
      a.style.display = open ? 'none' : 'block';
    });
  });

  // Make CTA open in new tab safely if it's external
  var ctas = document.querySelectorAll('a[href]');
  ctas.forEach(function(link){
    try{
      var href = link.getAttribute('href');
      if(href && href.indexOf('http')===0 && new URL(href).origin !== location.origin){
        link.setAttribute('target','_blank');
        link.setAttribute('rel','noopener noreferrer');
      }
    }catch(e){}
  });
});
"} 
